/usr/bin/zsh -lc "python3 -B - <<'PY'
import json, pathlib, subprocess, sys
root = pathlib.Path('/tmp/kk-batch-report-review-WhasQ2')
probe = '''import json, app
cases=[]
for setting in (False, True):
    app.DETAILED_REPORT = setting
    for mode in (None, False, True):
        for values in ([], [2,4], [3], [-2,4], [0,0], [1,2]):
            try:
                result = {'value': app.report(values, detailed=mode)}
            except Exception as exc:
                result = {'error': type(exc).__name__, 'message': str(exc)}
            cases.append({'setting': setting, 'mode': mode, 'values': values, 'result': result})
print(json.dumps(cases))
'''
results={}
for revision in ('historical','candidate'):
    output=subprocess.check_output([sys.executable,'-B','-c',probe],cwd=root/revision,text=True)
    results[revision]=json.loads(output)
for before, after in zip(results['historical'],results['candidate']):
    expected=dict(before['result'])
    if 'value' in expected:
        expected['value']=expected['value'].replace('Items: ', 'Records: ', 1)
    assert after['result']==expected, (before,after)
print('36 paired baseline/candidate scenarios matched with only the requested count-label change.')
print('Covered both default settings, omitted and explicit modes, empty, populated, singleton, signed, zero, and fractional-mean inputs.')
print('Detailed empty outcome, identical in HEAD and index:', json.dumps([row for row in results['candidate'] if row['values']==[] and row['result'].get('error')]))
(root/'verification.json').write_text(json.dumps({'command':'python3 -B source-isolated probes; paired assertion after replacing Items prefix with Records', 'cases':results},indent=2)+'\\n')
(root/'verification.json').chmod(0o444)
PY"

